<style>
.mela-legal { --legal-blue:#2f5597; --legal-navy:#173b67; --legal-text:#26364a; --legal-muted:#667085; --legal-border:#dce5f1; background:#f6f8fc; color:var(--legal-text); font-family:'Poppins',sans-serif; }
.mela-legal * { box-sizing:border-box; }
.mela-legal-hero { padding:72px 24px 64px; background:linear-gradient(135deg,#173b67,#234f86); color:#fff; }
.mela-legal-container { width:min(1120px,calc(100% - 40px)); margin:0 auto; }
.mela-legal-badge { display:inline-flex; padding:7px 14px; border:1px solid rgba(255,255,255,.22); border-radius:999px; background:rgba(255,255,255,.1); color:rgba(255,255,255,.88); font-size:.72rem; font-weight:600; letter-spacing:.12em; text-transform:uppercase; }
.mela-legal-hero h1 { max-width:800px; margin:18px 0 14px; color:#fff; font-size:clamp(2rem,4vw,3.2rem); line-height:1.08; letter-spacing:-.035em; }
.mela-legal-hero p { max-width:760px; margin:0; color:rgba(255,255,255,.78); font-size:1rem; line-height:1.7; }
.mela-legal-meta { display:flex; flex-wrap:wrap; gap:10px 24px; margin-top:22px; color:rgba(255,255,255,.68); font-size:.82rem; }
.mela-legal-body { padding:54px 0 72px; }
.mela-legal-layout { display:grid; grid-template-columns:260px minmax(0,1fr); gap:30px; align-items:start; }
.mela-legal-toc { position:sticky; top:92px; overflow:hidden; border:1px solid var(--legal-border); border-radius:14px; background:#fff; box-shadow:0 10px 28px rgba(23,59,103,.06); }
.mela-legal-toc strong { display:block; padding:16px 18px 12px; color:var(--legal-navy); }
.mela-legal-toc a { display:block; padding:9px 18px; border-left:3px solid transparent; color:#52647e; font-size:.82rem; text-decoration:none; }
.mela-legal-toc a:hover { border-left-color:var(--legal-blue); background:#f2f6fc; color:var(--legal-blue); }
.mela-legal-toc div { padding-bottom:14px; }
.mela-legal-document { padding:34px 38px; border:1px solid var(--legal-border); border-radius:14px; background:#fff; box-shadow:0 14px 36px rgba(23,59,103,.07); }
.mela-legal-document section { scroll-margin-top:100px; padding:0 0 26px; margin:0 0 28px; border-bottom:1px solid #e8eef6; }
.mela-legal-document section:last-child { margin-bottom:0; padding-bottom:0; border-bottom:0; }
.mela-legal-document h2 { margin:0 0 12px; color:var(--legal-navy); font-size:1.25rem; line-height:1.35; }
.mela-legal-document h3 { margin:18px 0 8px; color:#274f82; font-size:1rem; }
.mela-legal-document p,.mela-legal-document li { color:#4a5d78; font-size:.92rem; line-height:1.8; }
.mela-legal-document p { margin:0 0 12px; }
.mela-legal-document ul { margin:8px 0 14px; padding-left:22px; }
.mela-legal-document a { color:var(--legal-blue); }
.mela-legal-callout { padding:16px 18px; border-left:4px solid var(--legal-blue); border-radius:0 10px 10px 0; background:#f1f5fb; }
.mela-legal-links { display:flex; flex-wrap:wrap; gap:12px; margin-top:24px; }
.mela-legal-links a { padding:10px 16px; border:1px solid rgba(255,255,255,.26); border-radius:8px; color:#fff; text-decoration:none; font-size:.85rem; }
@media(max-width:850px){.mela-legal-layout{grid-template-columns:1fr}.mela-legal-toc{position:static}.mela-legal-document{padding:26px 22px}}
@media(max-width:575px){.mela-legal-container{width:min(100% - 28px,1120px)}.mela-legal-hero{padding:54px 0 48px}.mela-legal-body{padding:34px 0 52px}}
</style>
